"""Run all benchmarks and record the results in ``results.md``.

Run from the project root: ``python benchmark/run_all.py`` (about 20 s).
"""

from pathlib import Path

import bench_loop_vs_vectorised

from numcompute_stream.benchmarking import environment_info

RESULTS = Path(__file__).with_name("results.md")


def main():
    env = environment_info()
    sections = ["# Benchmark Results", "",
                "Generated by `benchmark/run_all.py`. Environment: "
                + ", ".join(f"{key} {value}" for key, value in env.items()) + ".", "",
                bench_loop_vs_vectorised.run(),
                "## (b) Effect of `buffer_size` (accuracy and retraining time)", "",
                "Not run yet.", ""]
    RESULTS.write_text("\n".join(sections))
    print(f"Wrote {RESULTS}")


if __name__ == "__main__":
    main()
